77: export async function scoreAudience(brief: Brief): Promise<AudienceFit> {
78:   const [columns, tracts] = await Promise.all([
79:     readAnalysisJson<TractColumn[]>("columns.json"),
80:     readAnalysisCsv("nyc_tracts.csv"),
81:   ]);
82: 
83:   // Without gateway credentials, or if Jev fails, the keyword stand-in keeps
84:   // the page working, and `source` tells the page which one it got. Locally the
85:   // credential is AI_GATEWAY_API_KEY; on a Vercel deployment the AI SDK uses
86:   // the project's OIDC token when no key is set.
87:   let weights: ColumnWeight[];
88:   let source: AudienceFit["source"] = "jev";
89:   if (!hasAudienceCredentials()) {
90:     console.warn("No AI_GATEWAY_API_KEY or VERCEL_OIDC_TOKEN; weighting the audience by keywords instead of Jev.");
91:     weights = keywordWeights(columns, brief.targetCustomer);
92:     source = "keywords";
93:   } else {
94:     try {
95:       weights = await jevWeights(columns, brief);
96:     } catch (error) {
97:       console.error("Jev failed; weighting the audience by keywords instead.", error);
98:       weights = keywordWeights(columns, brief.targetCustomer);
99:       source = "keywords";
100:     }
101:   }
102: 
103:   const markets = new Set<string>(brief.markets);
104:   const raw: [string, number][] = [];
105:   for (const tract of tracts) {
106:     if (!markets.has(tract.borough)) continue;
107:     let sum = 0;
108:     let magnitude = 0;
109:     for (const [i, w] of weights.entries()) {
110:       if (w.weight === 0) continue;
111:       sum += w.weight * Number(tract[columns[i].scaled]);
112:       magnitude += Math.abs(w.weight);
113:     }
114:     raw.push([tract.geoid, magnitude ? sum / magnitude : 0]);
115:   }
116: 
117:   // Rescale by rank so the strongest tracts reach 1 whatever the weights.
118:   raw.sort((a, b) => a[1] - b[1]);
119:   const scores: Record<string, number> = {};
120:   raw.forEach(([geoid], i) => {
121:     scores[geoid] = Number((i / Math.max(raw.length - 1, 1)).toFixed(4));
122:   });
123: 
124:   return { weights, scores, source };
125: }

