terraform {
  required_version = ">= 1.6"

  required_providers {
    vultr = {
      source  = "vultr/vultr"
      version = "~> 2.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

// The API key comes from VULTR_API_KEY, so no credential is committed.
provider "vultr" {}

variable "region" {
  description = "Vultr region ID for the instance. London keeps latency to Edinburgh low."
  type        = string
  default     = "lhr"
}

variable "plan" {
  description = "Vultr plan ID. A GPU plan runs the decision model on Vultr Cloud GPU; a CPU plan also works but scores slower. List plans with `curl -s -H \"Authorization: Bearer $VULTR_API_KEY\" 'https://api.vultr.com/v2/plans?type=vcg'`."
  type        = string
  default     = "vcg-a16-1c-6gb"
}

variable "os_name" {
  description = "Exact OS name to install, as listed by the Vultr API."
  type        = string
  default     = "Ubuntu 24.04 LTS x64"
}

variable "model" {
  description = "System One decision model to pull with Ollama, for example clef-flash or tev1:4b."
  type        = string
  default     = "clef-flash"
}

variable "instance_label" {
  description = "Label for the instance in the Vultr console."
  type        = string
  default     = "placewise-decision-model"
}

variable "ssh_cidr" {
  description = "IPv4 CIDR allowed to reach SSH. Narrow it to your own address when you can."
  type        = string
  default     = "0.0.0.0/0"
}

variable "acme_email" {
  description = "Contact address for the Let's Encrypt certificate Caddy requests. It is never validated."
  type        = string
  default     = "admin@example.com"
}

data "vultr_os" "ubuntu" {
  filter {
    name   = "name"
    values = [var.os_name]
  }
}

// Bearer token Caddy requires before it forwards a request to Ollama, which
// has no authentication of its own.
resource "random_password" "systemone" {
  length  = 48
  special = false
}

resource "vultr_firewall_group" "model" {
  description = var.instance_label
}

resource "vultr_firewall_rule" "ssh" {
  firewall_group_id = vultr_firewall_group.model.id
  protocol          = "tcp"
  ip_type           = "v4"
  subnet            = split("/", var.ssh_cidr)[0]
  subnet_size       = tonumber(split("/", var.ssh_cidr)[1])
  port              = "22"
  notes             = "ssh"
}

resource "vultr_firewall_rule" "http" {
  firewall_group_id = vultr_firewall_group.model.id
  protocol          = "tcp"
  ip_type           = "v4"
  subnet            = "0.0.0.0"
  subnet_size       = 0
  port              = "80"
  notes             = "acme"
}

resource "vultr_firewall_rule" "https" {
  firewall_group_id = vultr_firewall_group.model.id
  protocol          = "tcp"
  ip_type           = "v4"
  subnet            = "0.0.0.0"
  subnet_size       = 0
  port              = "443"
  notes             = "systemone"
}

resource "vultr_instance" "model" {
  label             = var.instance_label
  region            = var.region
  plan              = var.plan
  os_id             = data.vultr_os.ubuntu.id
  hostname          = var.instance_label
  firewall_group_id = vultr_firewall_group.model.id
  enable_ipv6       = false
  user_data = templatefile("${path.module}/cloud-init.yaml.tftpl", {
    model = var.model
    token = random_password.systemone.result
    email = var.acme_email
  })
}

// Caddy gets a real certificate because <ip>.sslip.io resolves to the instance.
output "url" {
  description = "Base URL for the System One endpoint; append /v1/systemone."
  value       = "https://${vultr_instance.model.main_ip}.sslip.io"
}

output "token" {
  description = "Bearer token the endpoint requires."
  value       = random_password.systemone.result
  sensitive   = true
}

output "model" {
  value = var.model
}

output "instance_ip" {
  value = vultr_instance.model.main_ip
}

