    .filter((l) => l.includes("=") && !l.startsWith("#"))
    .map((l) => [l.slice(0, l.indexOf("=")), l.slice(l.indexOf("=") + 1)]),
);

const columns = JSON.parse(readFileSync("/home/pixel/code/htb-2026/data/analysis/columns.json", "utf8"));
const model = process.argv[2] ?? "clef-flash";
const levels = [
  "Strongly against: the target customers are much less likely to have this trait.",
  "Against: the target customers are somewhat less likely to have this trait.",
  "Not relevant: the description says nothing either way about this trait.",
  "For: the target customers are somewhat more likely to have this trait.",
  "Strongly for: the target customers are much more likely to have this trait.",
];

const body = {
  model,
  state: {
    "target customer": "single professionals in their late twenties and thirties who live in Manhattan and Brooklyn",
    startup: "a dating app for people looking for a serious relationship",
    industry: "consumer apps",
  },
  questions: Object.fromEntries(
    columns.map((c) => [
      c.name,
      {
        type: "score",
        instructions: `How does this trait of an area's ${c.measures === "lives" ? "residents" : c.measures === "works" ? "workers" : "passers-by"} relate to the startup's target customers? Trait: ${c.description}.`,
        criteria: levels,
      },
    ]),
  ),
};

for (const run of [1, 2]) {
  const started = Date.now();
  const response = await fetch(env.SYSTEMONE_BASE_URL + "/v1/systemone", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${env.SYSTEMONE_API_TOKEN}` },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(120_000),
  });
  const seconds = ((Date.now() - started) / 1000).toFixed(1);
  if (!response.ok) {
    console.log(`run ${run}: http ${response.status} in ${seconds}s`, (await response.text()).slice(0, 200));
    continue;
  }
  const json = await response.json();
  const weights = Object.entries(json.answers).map(([name, a]) => {
    const top = levels.length - 1;
    let level = a.score;
    if (a.probabilities) {
      const entries = Object.entries(a.probabilities).map(([k, p]) => [Number(k), p]);
      const total = entries.reduce((s, [, p]) => s + p, 0);
      if (total > 0) level = entries.reduce((s, [i, p]) => s + i * p, 0) / total;
    }
