const read = (line: string) => {
  if (!line.trim()) return;
  const event = JSON.parse(line) as {
    type: string;
    fit?: AudienceFit & { answered: number; total: number };
    message?: string;
  };
  if (event.type === "error") throw new Error(event.message ?? "Scoring failed");
  if (event.type === "fit" && event.fit) {
    complete = event.fit;
    onFit(event.fit);
  }
};

